type-definitions.type:

interface User {
  id: string;
  email: string;
  firstName: string | null;
  lastName: string | null;
  role: 'admin' | 'interviewer' | 'interviewee';
  organizationId: string | null;
  mfaEnabled: boolean;
  emailVerified: boolean;
  createdAt: string;
  updatedAt: string;
}


interface Session {
  id: string;
  interviewerId: string;
  intervieweeId: string | null;
  intervieweeEmail: string | null;
  organizationId: string;
  status: 'scheduled' | 'active' | 'ended' | 'cancelled';
  sessionToken: string | null;
  scheduledStart: string | null;
  actualStart: string | null;
  actualEnd: string | null;
  durationMinutes: number | null;
  riskScore: number | null;
  createdAt: string;
  updatedAt: string;
  questions?: Question[];
  interviewer?: User;
  interviewee?: User;
}


interface Question {
  id: string;
  sessionId: string;
  questionText: string;
  difficulty: 'easy' | 'medium' | 'hard' | 'expert' | null;
  expectedDurationSeconds: number | null;
  askedAt: string | null;
  orderIndex: number;
}


interface SecurityEvent {
  id: string;
  sessionId: string;
  eventType: SecurityEventType;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  metadata: Record<string, unknown>;
  timestamp: string;
}

type SecurityEventType =
  | 'suspicious_process'
  | 'screen_recording_detected'
  | 'vm_detected'
  | 'window_focus_changed'
  | 'multi_monitor_detected'
  | 'unauthorized_browser'
  | 'copy_paste_detected'
  | 'keyboard_shortcut_blocked';


interface GazeData {
  gazeX: number; // 0-1 normalized
  gazeY: number; // 0-1 normalized
  isOffScreen: boolean;
  offScreenDirection: 'left' | 'right' | 'up' | 'down' | 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right' | null;
  confidence: number; // 0-1
  timestamp: string;
  userId?: string;
}


interface AIAnalysisResult {
  analysisId: string;
  questionId: string;
  riskScore: number; // 0-1
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  isAiGenerated: boolean;
  confidence: number; // 0-1
  similarityScores: {
    gpt4: number;
    claude: number;
    gemini: number;
  };
  perplexityScore: number;
  flags: string[];
}


interface SessionReport {
  id: string;
  sessionId: string;
  session: Session;
  participants: {
    interviewer: User;
    interviewee: User | null;
  };
  overallRiskScore: number;
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  assessment: 'pass' | 'review_required' | 'fail';
  riskBreakdown: {
    aiDetectionScore: number;
    aiDetectionWeight: number;
    securityEventsScore: number;
    securityEventsWeight: number;
    gazeAnomalyScore: number;
    gazeAnomalyWeight: number;
    timingAnomalyScore: number;
    timingAnomalyWeight: number;
  };
  questionsAnalysis: QuestionAnalysis[];
  securityEvents: {
    total: number;
    bySeverity: Record<string, number>;
    events: SecurityEvent[];
  };
  gazeTracking: {
    totalEvents: number;
    offScreenPercentage: number;
    averageConfidence: number;
  };
  recommendations: Recommendation[];
  generatedAt: string;
}

interface Recommendation {
  type: 'action' | 'warning' | 'info';
  category: 'integrity' | 'security' | 'technical';
  title: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  actionRequired: boolean;
  description: string;
}


interface ApiResponse<T> {
  success: boolean;
  data: T;
  meta?: {
    timestamp: string;
    requestId: string;
  };
}

interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    statusCode: number;
    details?: Record<string, unknown>;
  };
  meta?: {
    timestamp: string;
    requestId: string;
  };
}

interface PaginatedResponse<T> {
  success: boolean;
  data: T[];
  pagination: {
    page: number;
    pageSize: number;
    totalPages: number;
    totalItems: number;
    hasNext: boolean;
    hasPrev: boolean;
  };
}


interface AuthTokens {
  accessToken: string;
  refreshToken: string;
  expiresIn: number; // seconds
}

store.state:

interface AuthState {
  user: User | null;
  tokens: AuthTokens | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  mfaRequired: boolean;
  mfaToken: string | null;
}

store.actions:

interface AuthActions {
  setUser: (user: User) => void;
  setTokens: (tokens: AuthTokens) => void;
  setMfaRequired: (required: boolean, token?: string) => void;
  login: (email: string, password: string) => Promise<void>;
  register: (data: RegisterData) => Promise<void>;
  verifyMfa: (code: string) => Promise<void>;
  logout: () => void;
  refreshToken: () => Promise<void>;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  clearError: () => void;
}

store.state:

interface SessionState {
  currentSession: Session | null;
  currentQuestions: Question[];
  currentQuestionIndex: number;
  isSessionActive: boolean;
  sessionStartTime: number | null;
  participants: Participant[];
}

interface Participant {
  userId: string;
  role: string;
  name: string;
  online: boolean;
}

store.actions:

interface SessionActions {
  setCurrentSession: (session: Session | null) => void;
  setCurrentQuestions: (questions: Question[]) => void;
  startSession: () => void;
  endSession: () => void;
  nextQuestion: () => void;
  previousQuestion: () => void;
  goToQuestion: (index: number) => void;
  addParticipant: (participant: Participant) => void;
  removeParticipant: (userId: string) => void;
  updateParticipantStatus: (userId: string, online: boolean) => void;
  clearSession: () => void;
}

store.state:

interface RealtimeState {
  securityEvents: SecurityEvent[];
  gazeData: GazeData[];
  chatMessages: ChatMessage[];
  connectionStatus: 'connecting' | 'connected' | 'disconnected' | 'error';
  lastPingLatency: number | null;
}

interface ChatMessage {
  id: string;
  sessionId: string;
  senderId: string;
  senderRole: string;
  message: string;
  timestamp: string;
}

store.actions:

interface RealtimeActions {
  addSecurityEvent: (event: SecurityEvent) => void;
  addGazeData: (data: GazeData) => void;
  addChatMessage: (message: ChatMessage) => void;
  setConnectionStatus: (status: ConnectionStatus) => void;
  setPingLatency: (latency: number) => void;
  clearSecurityEvents: () => void;
  clearGazeData: () => void;
  clearChatMessages: () => void;
  clearAll: () => void;
}

store.state:

interface UIState {
  theme: 'light' | 'dark' | 'system';
  sidebarOpen: boolean;
  soundAlertsEnabled: boolean;
  modal: {
    isOpen: boolean;
    type: string | null;
    data: unknown;
  };
}

store.actions:

interface UIActions {
  setTheme: (theme: 'light' | 'dark' | 'system') => void;
  toggleSidebar: () => void;
  setSidebarOpen: (open: boolean) => void;
  toggleSoundAlerts: () => void;
  openModal: (type: string, data?: unknown) => void;
  closeModal: () => void;
}

