component.props:

interface VideoPlayerProps {
  sessionId: string;
  showGazeOverlay?: boolean;
  onConnectionChange?: (connected: boolean) => void;
  onQualityChange?: (quality: string) => void;
}


interface SecurityEventsDashboardProps {
  sessionId: string;
  maxEvents?: number;
  showFilters?: boolean;
  onEventClick?: (event: SecurityEvent) => void;
}


interface GazeHeatmapProps {
  sessionId: string;
  width: number;
  height: number;
  showStatistics?: boolean;
}


interface AIDetectionResultsProps {
  sessionId: string;
  questionId?: string;
}


interface QuestionTimelineProps {
  sessionId: string;
  questions: Question[];
  currentQuestionIndex: number;
  onQuestionSelect?: (index: number) => void;
}


interface SessionControlsProps {
  sessionId: string;
  status: SessionStatus;
  onStart?: () => void;
  onEnd?: () => void;
  onCancel?: () => void;
}
